def q(s): return json.dumps(str(s), ensure_ascii=False)
def legacy_note(eid,p,context='entry'):
    raw=legacy[eid]; tags=', '.join(map(str, raw.get('tg',[])[:6])); obj=str(raw.get('o',''))[:220].replace('\n',' ')
    obj=re.sub(r'\b(?:Qwen|GPT|Claude|Gemini|Grok|Llama|DeepSeek|OpenAI|Anthropic|Google|Sora)[A-Za-z0-9 .\-]*','[legacy-model-mention]',obj)
    tags=re.sub(r'\b(?:Qwen|GPT|Claude|Gemini|Grok|Llama|DeepSeek|OpenAI|Anthropic|Google|Sora)[A-Za-z0-9 .\-]*','[legacy-model-mention]',tags)
    return f"Legacy preservation note for {eid} / {context}: original legacy objective and tags are retained as audit context inside the source corpus, not treated as verified mechanism; objective excerpt = {obj}; tag excerpt = {tags}; v2 labels unsafe-operational or unsupported parts as canary-only, hypothesis-only, or not-verified."
def paragraph(p,eid,theme,idx):
    marker=f"{eid} {theme} checkpoint {idx+1}"; kin='; '.join(p['kin'][:3]); variants=', '.join(p['variants']); defenses=', '.join(p['defenses']); risks=', '.join(p['risks'])
    templates=[
        f"{marker}: {p['safe_name']} is preserved as a legacy concept but normalized into a defensive measurement entry: {p['thesis']} with anchors {p['anchors']}.",
        f"{marker}: the boundary is {p['safe_boundary']}; protected material is replaced with canaries and every result is a local ESTIMATE tied to the tested system.",
        f"{marker}: the core seam is {p['core']}; related entries are {kin}, but kinship does not prove shared efficacy or identical internals.",
        f"{marker}: a valid battery includes benign controls, overt canaries, transformed canaries, coverage or source ablations, and output review so the signal is policy invariance.",
        f"{marker}: variants in scope include {variants}, implemented as inert labels, synthetic traces, or audit markers rather than operational bypass instructions.",
        f"{marker}: primary controls are {defenses}; they count only when retesting shows transformed canaries handled safely while benign work remains usable.",
        f"{marker}: the risk ledger includes {risks}, and observed outcomes are separated from HYPOTHESIS claims about multimodal anchoring, sampling, expert routing, persona drift, or cross-lingual embeddings.",
        f"{marker}: observability requires prompt hashes, canary IDs, source labels, coverage metrics, intermediate traces where safe, and final outputs.",
        f"{marker}: closure requires provenance preserved, canary-safe behavior, benign pass-through, and report language that keeps legacy artifacts visible but not overclaimed.",
        f"{marker}: overblocking is a governance issue; a system that blocks all multimodal inputs, parameter variation, technical style, persona comparison, or minority languages has not cleanly solved the boundary.",
        f"{marker}: unsupported internals such as expert rerouting, forced forbidden-token selection, persona belief, or embedding-gap universality remain HYPOTHESIS unless instrumented.",
        f"{marker}: the field lesson is to measure invariance, authenticate sources, preserve evidence, and bind policy outside superficial form."
    ]; return templates[idx%len(templates)]
